import { Adapter } from '@node-escpos/adapter';
import Noble from '@abandonware/noble';

interface Device {
    peripheral: Noble.Peripheral;
    characteristic: Noble.Characteristic;
}
/**
 * Bluetooth device
 * @param {[type]} port
 * @param {[type]} options
 */
declare class Bluetooth extends Adapter<[timeout?: number]> {
    private devices;
    private address;
    constructor(address: string, options: any);
    /**
     * List Printers
     * @returns {[Device]}
     */
    list(): Device[];
    get device(): Device | null;
    /**
     * open device
     * @param  {Function} callback
     * @return {[type]}
     */
    open(callback?: (error: Error | null) => void): this;
    /**
     * write data to bluetooth device
     * @param  {[type]}   data      [description]
     * @param  {Function} callback [description]
     * @return {[type]}            [description]
     */
    write(data: Buffer | string, callback?: (error: Error | null) => void): this;
    /**
     * close device
     * @param  {Function} callback  [description]
     * @param  {int}      timeout   [allow manual timeout for emulated COM ports (bluetooth, ...)]
     * @return {[type]} [description]
     */
    close(callback?: (error: Error | null, device: Device) => void, timeout?: number): this;
    /**
     * read buffer from the printer
     * @param  {Function} callback
     * @return {Serial}
     */
    read(callback?: (data: Buffer) => void): this;
}

export { Device, Bluetooth as default };
